    CreateProjectInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectDescription, location_name: 'description', traits: {"smithy.api#documentation" => "<p>A description that makes the build project easy to identify.</p>"}))
    CreateProjectInput.add_member(:source, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSource, location_name: 'source', traits: {"smithy.api#documentation" => "<p>Information about the build input source code for the build project.</p>", "smithy.api#required" => {}}))
    CreateProjectInput.add_member(:secondary_sources, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSources, location_name: 'secondarySources', traits: {"smithy.api#documentation" => "<p>An array of <code>ProjectSource</code> objects. </p>"}))
    CreateProjectInput.add_member(:source_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceVersion', traits: {"smithy.api#documentation" => "<p>A version of the build input to be built for this project. If not specified, the latest\n            version is used. If specified, it must be one of: </p>\n         <ul>\n            <li>\n               <p>For CodeCommit: the commit ID, branch, or Git tag to use.</p>\n            </li>\n            <li>\n               <p>For GitHub: the commit ID, pull request ID, branch name, or tag name that\n          corresponds to the version of the source code you want to build. If a pull\n          request ID is specified, it must use the format <code>pr/pull-request-ID</code>\n          (for example <code>pr/25</code>). If a branch name is specified, the branch's\n          HEAD commit ID is used. If not specified, the default branch's HEAD commit ID is\n          used.</p>\n            </li>\n            <li>\n               <p>For GitLab: the commit ID, branch, or Git tag to use.</p>\n            </li>\n            <li>\n               <p>For Bitbucket: the commit ID, branch name, or tag name that corresponds to the\n          version of the source code you want to build. If a branch name is specified, the\n          branch's HEAD commit ID is used. If not specified, the default branch's HEAD\n          commit ID is used.</p>\n            </li>\n            <li>\n               <p>For Amazon S3: the version ID of the object that represents the build input ZIP\n          file to use.</p>\n            </li>\n         </ul>\n         <p>If <code>sourceVersion</code> is specified at the build level, then that version takes\n            precedence over this <code>sourceVersion</code> (at the project level). </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-source-version.html\">Source Version Sample\n                with CodeBuild</a> in the <i>CodeBuild User Guide</i>. \n    </p>"}))
    CreateProjectInput.add_member(:secondary_source_versions, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSecondarySourceVersions, location_name: 'secondarySourceVersions', traits: {"smithy.api#documentation" => "<p>An array of <code>ProjectSourceVersion</code> objects. If\n      <code>secondarySourceVersions</code> is specified at the build level, then they take\n      precedence over these <code>secondarySourceVersions</code> (at the project level).\n    </p>"}))
    CreateProjectInput.add_member(:artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectArtifacts, location_name: 'artifacts', traits: {"smithy.api#documentation" => "<p>Information about the build output artifacts for the build project.</p>", "smithy.api#required" => {}}))
