    CreateProjectInput.add_member(:service_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'serviceRole', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that enables CodeBuild to interact with dependent Amazon Web Services services\n      on behalf of the Amazon Web Services account.</p>", "smithy.api#required" => {}}))
    CreateProjectInput.add_member(:timeout_in_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildTimeOut, location_name: 'timeoutInMinutes', traits: {"smithy.api#documentation" => "<p>How long, in minutes, from 5 to 2160 (36 hours), for CodeBuild to wait before it times out\n      any build that has not been marked as completed. The default is 60 minutes.</p>"}))
    CreateProjectInput.add_member(:queued_timeout_in_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeOut, location_name: 'queuedTimeoutInMinutes', traits: {"smithy.api#documentation" => "<p>The number of minutes a build is allowed to be queued before it times out. </p>"}))
    CreateProjectInput.add_member(:encryption_key, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'encryptionKey', traits: {"smithy.api#documentation" => "<p>The Key Management Service customer master key (CMK) to be used for encrypting the build output\n      artifacts.</p>\n         <note>\n            <p>You can use a cross-account KMS key to encrypt the build output artifacts if your\n        service role has permission to that key. </p>\n         </note>\n         <p>You can specify either the Amazon Resource Name (ARN) of the CMK or, if available, the CMK's alias (using\n        the format <code>alias/<alias-name></code>).\n    </p>"}))
    CreateProjectInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>A list of tag key and value pairs associated with this build project.</p>\n         <p>These tags are available for use by Amazon Web Services services that support CodeBuild build project\n      tags.</p>"}))
    CreateProjectInput.add_member(:vpc_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcConfig, location_name: 'vpcConfig', traits: {"smithy.api#documentation" => "<p>VpcConfig enables CodeBuild to access resources in an Amazon VPC.</p>\n         <note>\n            <p>If you're using compute fleets during project creation, do not provide vpcConfig.</p>\n         </note>"}))
    CreateProjectInput.add_member(:badge_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'badgeEnabled', traits: {"smithy.api#documentation" => "<p>Set this to true to generate a publicly accessible URL for your project's build\n        badge.</p>"}))
    CreateProjectInput.add_member(:logs_config, Smithy::Schema::Shapes::ShapeRef.new(shape: LogsConfig, location_name: 'logsConfig', traits: {"smithy.api#documentation" => "<p>Information about logs for the build project. These can be logs in CloudWatch Logs, logs\n      uploaded to a specified S3 bucket, or both. </p>"}))
    CreateProjectInput.add_member(:file_system_locations, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectFileSystemLocations, location_name: 'fileSystemLocations', traits: {"smithy.api#documentation" => "<p>\n      An array of <code>ProjectFileSystemLocation</code> objects for a CodeBuild build project. A <code>ProjectFileSystemLocation</code> object \n      specifies the <code>identifier</code>, <code>location</code>, <code>mountOptions</code>, \n      <code>mountPoint</code>, and <code>type</code> of a file system created using Amazon Elastic File System.\n  </p>"}))
    CreateProjectInput.add_member(:build_batch_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectBuildBatchConfig, location_name: 'buildBatchConfig', traits: {"smithy.api#documentation" => "<p>A <a>ProjectBuildBatchConfig</a>\n object that defines the batch build options\n            for the project.</p>"}))
    CreateProjectInput.add_member(:concurrent_build_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'concurrentBuildLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of concurrent builds that are allowed for this project.</p>\n         <p>New builds are only started if the current number of builds is less than or equal to this limit. \n  If the current build count meets this limit, new builds are throttled and are not run.</p>"}))
    CreateProjectInput.add_member(:auto_retry_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'autoRetryLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of additional automatic retries after a failed build. For example, if the \n      auto-retry limit is set to 2, CodeBuild will call the <code>RetryBuild</code> API to automatically \n      retry your build for up to 2 additional times.</p>"}))
