    CreateWebhookInput.add_member(:branch_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'branchFilter', traits: {"smithy.api#documentation" => "<p>A regular expression used to determine which repository branches are built when a\n      webhook is triggered. If the name of a branch matches the regular expression, then it is\n      built. If <code>branchFilter</code> is empty, then all branches are built.</p>\n         <note>\n            <p>It is recommended that you use <code>filterGroups</code> instead of\n        <code>branchFilter</code>. </p>\n         </note>"}))
    CreateWebhookInput.add_member(:filter_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterGroups, location_name: 'filterGroups', traits: {"smithy.api#documentation" => "<p>An array of arrays of <code>WebhookFilter</code> objects used to determine which\n      webhooks are triggered. At least one <code>WebhookFilter</code> in the array must\n      specify <code>EVENT</code> as its <code>type</code>. </p>\n         <p>For a build to be triggered, at least one filter group in the\n      <code>filterGroups</code> array must pass. For a filter group to pass, each of its\n      filters must pass. </p>"}))
    CreateWebhookInput.add_member(:build_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WebhookBuildType, location_name: 'buildType', traits: {"smithy.api#documentation" => "<p>Specifies the type of build this webhook will trigger.</p>\n         <note>\n            <p>\n               <code>RUNNER_BUILDKITE_BUILD</code> is only available for <code>NO_SOURCE</code> source type projects \n        configured for Buildkite runner builds. For more information about CodeBuild-hosted Buildkite runner builds, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-runner-buildkite.html\">Tutorial: Configure a CodeBuild-hosted Buildkite runner</a> in the <i>CodeBuild\n        user guide</i>.</p>\n         </note>"}))
    CreateWebhookInput.add_member(:manual_creation, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'manualCreation', traits: {"smithy.api#documentation" => "<p>If manualCreation is true, CodeBuild doesn't create a webhook in GitHub and instead returns <code>payloadUrl</code> and \n      <code>secret</code> values for the webhook. The <code>payloadUrl</code> and <code>secret</code> values in the output can be \n      used to manually create a webhook within GitHub.</p>\n         <note>\n            <p>\n               <code>manualCreation</code> is only available for GitHub webhooks.</p>\n         </note>"}))
    CreateWebhookInput.add_member(:scope_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ScopeConfiguration, location_name: 'scopeConfiguration', traits: {"smithy.api#documentation" => "<p>The scope configuration for global or organization webhooks.</p>\n         <note>\n            <p>Global or organization webhooks are only available for GitHub and Github Enterprise webhooks.</p>\n         </note>"}))
    CreateWebhookInput.add_member(:pull_request_build_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PullRequestBuildPolicy, location_name: 'pullRequestBuildPolicy', traits: {"smithy.api#documentation" => "<p>A PullRequestBuildPolicy object that defines comment-based approval requirements for triggering builds on pull requests. This policy helps control when automated builds are executed based on contributor permissions and approval workflows.</p>"}))
