    DescribeTestCasesInput.add_member(:report_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reportArn', traits: {"smithy.api#documentation" => "<p>\n      The ARN of the report for which test cases are returned.\n    </p>", "smithy.api#required" => {}}))
    DescribeTestCasesInput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'nextToken', traits: {"smithy.api#documentation" => "<p>\n      During a previous call, the maximum number of items that can be returned is the value specified in\n      <code>maxResults</code>. If there more items in the list, then a unique string called a <i>nextToken</i>\n      is returned. To get the next batch of items in the list, call this operation again, adding the next token\n      to the call. To get all of the items in the list, keep calling this operation with each\n      subsequent next token that is returned, until no more next tokens are returned.\n    </p>"}))
    DescribeTestCasesInput.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: PageSize, location_name: 'maxResults', traits: {"smithy.api#documentation" => "<p>\n      The maximum number of paginated test cases returned per response. Use <code>nextToken</code> to iterate pages in\n      the list of returned <code>TestCase</code> objects. The default value is 100.\n    </p>"}))
