    Project.add_member(:created, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'created', traits: {"smithy.api#documentation" => "<p>When the build project was created, expressed in Unix time format.</p>"}))
    Project.add_member(:last_modified, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'lastModified', traits: {"smithy.api#documentation" => "<p>When the build project's settings were last modified, expressed in Unix time\n      format.</p>"}))
    Project.add_member(:webhook, Smithy::Schema::Shapes::ShapeRef.new(shape: Webhook, location_name: 'webhook', traits: {"smithy.api#documentation" => "<p>Information about a webhook that connects repository events to a build project in\n      CodeBuild.</p>"}))
    Project.add_member(:vpc_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcConfig, location_name: 'vpcConfig', traits: {"smithy.api#documentation" => "<p>Information about the VPC configuration that CodeBuild accesses.</p>"}))
    Project.add_member(:badge, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectBadge, location_name: 'badge', traits: {"smithy.api#documentation" => "<p>Information about the build badge for the build project.</p>"}))
    Project.add_member(:logs_config, Smithy::Schema::Shapes::ShapeRef.new(shape: LogsConfig, location_name: 'logsConfig', traits: {"smithy.api#documentation" => "<p>Information about logs for the build project. A project can create logs in CloudWatch Logs, an\n      S3 bucket, or both. </p>"}))
    Project.add_member(:file_system_locations, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectFileSystemLocations, location_name: 'fileSystemLocations', traits: {"smithy.api#documentation" => "<p>\n      An array of <code>ProjectFileSystemLocation</code> objects for a CodeBuild build project. A <code>ProjectFileSystemLocation</code> object \n      specifies the <code>identifier</code>, <code>location</code>, <code>mountOptions</code>, \n      <code>mountPoint</code>, and <code>type</code> of a file system created using Amazon Elastic File System.\n  </p>"}))
    Project.add_member(:build_batch_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectBuildBatchConfig, location_name: 'buildBatchConfig', traits: {"smithy.api#documentation" => "<p>A <a>ProjectBuildBatchConfig</a>\n object that defines the batch build\n            options for the project.</p>"}))
    Project.add_member(:concurrent_build_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'concurrentBuildLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of concurrent builds that are allowed for this project.</p>\n         <p>New builds are only started if the current number of builds is less than or equal to this limit. \n  If the current build count meets this limit, new builds are throttled and are not run.</p>"}))
    Project.add_member(:project_visibility, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectVisibilityType, location_name: 'projectVisibility'))
    Project.add_member(:public_project_alias, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'publicProjectAlias', traits: {"smithy.api#documentation" => "<p>Contains the project identifier used with the public build APIs. </p>"}))
    Project.add_member(:resource_access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'resourceAccessRole', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that enables CodeBuild to access the CloudWatch Logs and Amazon S3 artifacts for\n      the project's builds.</p>"}))
    Project.add_member(:auto_retry_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'autoRetryLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of additional automatic retries after a failed build. For example, if the \n      auto-retry limit is set to 2, CodeBuild will call the <code>RetryBuild</code> API to automatically \n      retry your build for up to 2 additional times.</p>"}))
    Project.type = Types::Project
    ProjectArns.member = Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString)
    ProjectArtifacts.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: ArtifactsType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of build output artifact. Valid values include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CODEPIPELINE</code>: The build project has build output generated\n                    through CodePipeline. </p>\n               <note>\n                  <p>The <code>CODEPIPELINE</code> type is not supported for\n                            <code>secondaryArtifacts</code>.</p>\n               </note>\n            </li>\n            <li>\n               <p>\n                  <code>NO_ARTIFACTS</code>: The build project does not produce any build\n                    output.</p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code>: The build project stores build output in Amazon S3.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ProjectArtifacts.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'location', traits: {"smithy.api#documentation" => "<p>Information about the build output artifact location:</p>\n         <ul>\n            <li>\n               <p>If <code>type</code> is set to <code>CODEPIPELINE</code>, CodePipeline ignores this\n                    value if specified. This is because CodePipeline manages its build output locations\n                    instead of CodeBuild.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>NO_ARTIFACTS</code>, this value is\n                    ignored if specified, because no build output is produced.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>S3</code>, this is the name of the output\n                    bucket.</p>\n            </li>\n         </ul>"}))
    ProjectArtifacts.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'path', traits: {"smithy.api#documentation" => "<p>Along with <code>namespaceType</code> and <code>name</code>, the pattern that CodeBuild\n            uses to name and store the output artifact:</p>\n         <ul>\n            <li>\n               <p>If <code>type</code> is set to <code>CODEPIPELINE</code>, CodePipeline ignores this\n                    value if specified. This is because CodePipeline manages its build output names instead\n                    of CodeBuild.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>NO_ARTIFACTS</code>, this value is\n                    ignored if specified, because no build output is produced.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>S3</code>, this is the path to the output\n                    artifact. If <code>path</code> is not specified, <code>path</code> is not\n                    used.</p>\n            </li>\n         </ul>\n         <p>For example, if <code>path</code> is set to <code>MyArtifacts</code>,\n                <code>namespaceType</code> is set to <code>NONE</code>, and <code>name</code> is set\n            to <code>MyArtifact.zip</code>, the output artifact is stored in the output bucket at\n                <code>MyArtifacts/MyArtifact.zip</code>.</p>"}))
    ProjectArtifacts.add_member(:namespace_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ArtifactNamespace, location_name: 'namespaceType', traits: {"smithy.api#documentation" => "<p>Along with <code>path</code> and <code>name</code>, the pattern that CodeBuild uses to\n            determine the name and location to store the output artifact:</p>\n         <ul>\n            <li>\n               <p>If <code>type</code> is set to <code>CODEPIPELINE</code>, CodePipeline ignores this\n                    value if specified. This is because CodePipeline manages its build output names instead\n                    of CodeBuild.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>NO_ARTIFACTS</code>, this value is\n                    ignored if specified, because no build output is produced.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>S3</code>, valid values include:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>BUILD_ID</code>: Include the build ID in the location of the\n                            build output artifact.</p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>NONE</code>: Do not include the build ID. This is the default if\n                                <code>namespaceType</code> is not specified.</p>\n                  </li>\n               </ul>\n            </li>\n         </ul>\n         <p>For example, if <code>path</code> is set to <code>MyArtifacts</code>,\n                <code>namespaceType</code> is set to <code>BUILD_ID</code>, and <code>name</code> is\n            set to <code>MyArtifact.zip</code>, the output artifact is stored in\n                <code>MyArtifacts/<build-ID>/MyArtifact.zip</code>.</p>"}))
    ProjectArtifacts.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'name', traits: {"smithy.api#documentation" => "<p>Along with <code>path</code> and <code>namespaceType</code>, the pattern that CodeBuild\n            uses to name and store the output artifact:</p>\n         <ul>\n            <li>\n               <p>If <code>type</code> is set to <code>CODEPIPELINE</code>, CodePipeline ignores this\n                    value if specified. This is because CodePipeline manages its build output names instead\n                    of CodeBuild.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>NO_ARTIFACTS</code>, this value is\n                    ignored if specified, because no build output is produced.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>S3</code>, this is the name of the output\n                    artifact object. If you set the name to be a forward slash (\"/\"), the artifact\n                    is stored in the root of the output bucket.</p>\n            </li>\n         </ul>\n         <p>For example:</p>\n         <ul>\n            <li>\n               <p> If <code>path</code> is set to <code>MyArtifacts</code>,\n                        <code>namespaceType</code> is set to <code>BUILD_ID</code>, and\n                        <code>name</code> is set to <code>MyArtifact.zip</code>, then the output\n                    artifact is stored in <code>MyArtifacts/<build-ID>/MyArtifact.zip</code>. </p>\n            </li>\n            <li>\n               <p> If <code>path</code> is empty, <code>namespaceType</code> is set to\n                        <code>NONE</code>, and <code>name</code> is set to \"<code>/</code>\", the\n                    output artifact is stored in the root of the output bucket. </p>\n            </li>\n            <li>\n               <p> If <code>path</code> is set to <code>MyArtifacts</code>,\n                        <code>namespaceType</code> is set to <code>BUILD_ID</code>, and\n                        <code>name</code> is set to \"<code>/</code>\", the output artifact is stored\n                    in <code>MyArtifacts/<build-ID></code>. </p>\n            </li>\n         </ul>"}))
    ProjectArtifacts.add_member(:packaging, Smithy::Schema::Shapes::ShapeRef.new(shape: ArtifactPackaging, location_name: 'packaging', traits: {"smithy.api#documentation" => "<p>The type of build output artifact to create:</p>\n         <ul>\n            <li>\n               <p>If <code>type</code> is set to <code>CODEPIPELINE</code>, CodePipeline ignores this\n                    value if specified. This is because CodePipeline manages its build output artifacts\n                    instead of CodeBuild.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>NO_ARTIFACTS</code>, this value is\n                    ignored if specified, because no build output is produced.</p>\n            </li>\n            <li>\n               <p>If <code>type</code> is set to <code>S3</code>, valid values include:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>NONE</code>: CodeBuild creates in the output bucket a folder that\n                            contains the build output. This is the default if <code>packaging</code>\n                            is not specified.</p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>ZIP</code>: CodeBuild creates in the output bucket a ZIP file that\n                            contains the build output.</p>\n                  </li>\n               </ul>\n            </li>\n         </ul>"}))
    ProjectArtifacts.add_member(:override_artifact_name, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'overrideArtifactName', traits: {"smithy.api#documentation" => "<p> If this flag is set, a name specified in the buildspec file overrides the artifact\n            name. The name specified in a buildspec file is calculated at build time and uses the\n            Shell Command Language. For example, you can append a date and time to your artifact\n            name so that it is always unique. </p>"}))
    ProjectArtifacts.add_member(:encryption_disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'encryptionDisabled', traits: {"smithy.api#documentation" => "<p> Set to true if you do not want your output artifacts encrypted. This option is valid\n            only if your artifacts type is Amazon S3. If this is set with another artifacts type, an\n            invalidInputException is thrown. </p>"}))
    ProjectArtifacts.add_member(:artifact_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'artifactIdentifier', traits: {"smithy.api#documentation" => "<p> An identifier for this artifact definition. </p>"}))
    ProjectArtifacts.add_member(:bucket_owner_access, Smithy::Schema::Shapes::ShapeRef.new(shape: BucketOwnerAccess, location_name: 'bucketOwnerAccess'))
    ProjectArtifacts.type = Types::ProjectArtifacts
    ProjectArtifactsList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectArtifacts)
    ProjectBadge.add_member(:badge_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'badgeEnabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Set this to true to generate a publicly accessible URL for your project's build\n            badge.</p>"}))
    ProjectBadge.add_member(:badge_request_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'badgeRequestUrl', traits: {"smithy.api#documentation" => "<p>The publicly-accessible URL through which you can access the build badge for your\n            project. </p>"}))
    ProjectBadge.type = Types::ProjectBadge
    ProjectBuildBatchConfig.add_member(:service_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'serviceRole', traits: {"smithy.api#documentation" => "<p>Specifies the service role ARN for the batch build project.</p>"}))
    ProjectBuildBatchConfig.add_member(:combine_artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'combineArtifacts', traits: {"smithy.api#documentation" => "<p>Specifies if the build artifacts for the batch build should be combined into a single\n            artifact location.</p>"}))
    ProjectBuildBatchConfig.add_member(:restrictions, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchRestrictions, location_name: 'restrictions', traits: {"smithy.api#documentation" => "<p>A <code>BatchRestrictions</code> object that specifies the restrictions for the batch\n            build.</p>"}))
    ProjectBuildBatchConfig.add_member(:timeout_in_mins, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'timeoutInMins', traits: {"smithy.api#documentation" => "<p>Specifies the maximum amount of time, in minutes, that the batch build must be completed in.</p>"}))
    ProjectBuildBatchConfig.add_member(:batch_report_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchReportModeType, location_name: 'batchReportMode', traits: {"smithy.api#documentation" => "<p>Specifies how build status reports are sent to the source provider for the batch build. This property is only used\n              when the source provider for your project is Bitbucket, GitHub, or GitHub Enterprise,\n              and your project is configured to report build statuses to the source provider.</p>\n         <dl>\n            <dt>REPORT_AGGREGATED_BATCH</dt>\n            <dd>\n               <p>(Default) Aggregate all of the build statuses into a single status report.</p>\n            </dd>\n            <dt>REPORT_INDIVIDUAL_BUILDS</dt>\n            <dd>\n               <p>Send a separate status report for each individual build.</p>\n            </dd>\n         </dl>"}))
    ProjectBuildBatchConfig.type = Types::ProjectBuildBatchConfig
    ProjectCache.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of cache used by the build project. Valid values include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NO_CACHE</code>: The build project does not use any cache.</p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code>: The build project reads and writes from and to S3.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LOCAL</code>: The build project stores a cache locally on a build host\n                    that is only available to that build host.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ProjectCache.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'location', traits: {"smithy.api#documentation" => "<p>Information about the cache location: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>NO_CACHE</code> or <code>LOCAL</code>: This value is ignored.</p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code>: This is the S3 bucket name/prefix.</p>\n            </li>\n         </ul>"}))
    ProjectCache.add_member(:modes, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectCacheModes, location_name: 'modes', traits: {"smithy.api#documentation" => "<p>An array of strings that specify the local cache modes. You can use one or more local\n            cache modes at the same time. This is only used for <code>LOCAL</code> cache\n            types.</p>\n         <p>Possible values are:</p>\n         <dl>\n            <dt>LOCAL_SOURCE_CACHE</dt>\n            <dd>\n               <p>Caches Git metadata for primary and secondary sources. After the cache is\n                        created, subsequent builds pull only the change between commits. This mode\n                        is a good choice for projects with a clean working directory and a source\n                        that is a large Git repository. If you choose this option and your project\n                        does not use a Git repository (GitHub, GitHub Enterprise, or Bitbucket), the\n                        option is ignored. </p>\n            </dd>\n            <dt>LOCAL_DOCKER_LAYER_CACHE</dt>\n            <dd>\n               <p>Caches existing Docker layers. This mode is a good choice for projects\n                        that build or pull large Docker images. It can prevent the performance\n                        issues caused by pulling large Docker images down from the network. </p>\n               <note>\n                  <ul>\n                     <li>\n                        <p>You can use a Docker layer cache in the Linux environment\n                                    only. </p>\n                     </li>\n                     <li>\n                        <p>The <code>privileged</code> flag must be set so that your\n                                    project has the required Docker permissions. </p>\n                     </li>\n                     <li>\n                        <p>You should consider the security implications before you use a\n                                    Docker layer cache. </p>\n                     </li>\n                  </ul>\n               </note>\n            </dd>\n            <dt>LOCAL_CUSTOM_CACHE</dt>\n            <dd>\n               <p>Caches directories you specify in the buildspec file. This mode is a good\n                        choice if your build scenario is not suited to one of the other three local\n                        cache modes. If you use a custom cache: </p>\n               <ul>\n                  <li>\n                     <p>Only directories can be specified for caching. You cannot specify\n                                individual files. </p>\n                  </li>\n                  <li>\n                     <p>Symlinks are used to reference cached directories. </p>\n                  </li>\n                  <li>\n                     <p>Cached directories are linked to your build before it downloads\n                                its project sources. Cached items are overridden if a source item\n                                has the same name. Directories are specified using cache paths in\n                                the buildspec file. </p>\n                  </li>\n               </ul>\n            </dd>\n         </dl>"}))
    ProjectCache.add_member(:cache_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'cacheNamespace', traits: {"smithy.api#documentation" => "<p>Defines the scope of the cache. You can use this namespace to share a cache across \n            multiple projects. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/caching-s3.html#caching-s3-sharing\">Cache sharing \n                between projects</a> in the <i>CodeBuild User Guide</i>.</p>"}))
    ProjectCache.type = Types::ProjectCache
    ProjectCacheModes.member = Smithy::Schema::Shapes::ShapeRef.new(shape: CacheMode)
    ProjectEnvironment.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of build environment to use for related builds.</p>\n         <note>\n            <p>If you're using compute fleets during project creation, <code>type</code> will be ignored.</p>\n         </note>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-env-ref-compute-types.html\">Build environment compute types</a> in the <i>CodeBuild\n                user guide</i>.</p>", "smithy.api#required" => {}}))
    ProjectEnvironment.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'image', traits: {"smithy.api#documentation" => "<p>The image tag or image digest that identifies the Docker image to use for this build\n            project. Use the following formats:</p>\n         <ul>\n            <li>\n               <p>For an image tag: <code><registry>/<repository>:<tag></code>. For\n                    example, in the Docker repository that CodeBuild uses to manage its Docker\n                    images, this would be <code>aws/codebuild/standard:4.0</code>. </p>\n            </li>\n            <li>\n               <p>For an image digest: <code><registry>/<repository>@<digest></code>.\n                    For example, to specify an image with the digest\n                    \"sha256:cbbf2f9a99b47fc460d422812b6a5adff7dfee951d8fa2e4a98caa0382cfbdbf,\" use\n                        <code><registry>/<repository>@sha256:cbbf2f9a99b47fc460d422812b6a5adff7dfee951d8fa2e4a98caa0382cfbdbf</code>.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-env-ref-available.html\">Docker images provided by CodeBuild</a> in the <i>CodeBuild user\n                guide</i>.</p>", "smithy.api#required" => {}}))
    ProjectEnvironment.add_member(:compute_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeType, location_name: 'computeType', traits: {"smithy.api#documentation" => "<p>Information about the compute resources the build project uses. Available values\n            include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ATTRIBUTE_BASED_COMPUTE</code>: Specify the amount of vCPUs, memory, disk space, and the type of machine.</p>\n               <note>\n                  <p> If you use <code>ATTRIBUTE_BASED_COMPUTE</code>, you must define your attributes by using <code>computeConfiguration</code>. CodeBuild \n                        will select the cheapest instance that satisfies your specified attributes. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-env-ref-compute-types.html#environment-reserved-capacity.types\">Reserved capacity environment \n                        types</a> in the <i>CodeBuild User Guide</i>.</p>\n               </note>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_GENERAL1_SMALL</code>: Use up to 4 GiB memory and 2 vCPUs for\n                    builds.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_GENERAL1_MEDIUM</code>: Use up to 8 GiB memory and 4 vCPUs for\n                    builds.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_GENERAL1_LARGE</code>: Use up to 16 GiB memory and 8 vCPUs for\n                    builds, depending on your environment type.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_GENERAL1_XLARGE</code>: Use up to 72 GiB memory and 36 vCPUs for\n                    builds, depending on your environment type.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_GENERAL1_2XLARGE</code>: Use up to 144 GiB memory, 72 vCPUs, and\n                    824 GB of SSD storage for builds. This compute type supports Docker images up to\n                    100 GB uncompressed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_LAMBDA_1GB</code>: Use up to 1 GiB memory for\n                    builds. Only available for environment type <code>LINUX_LAMBDA_CONTAINER</code> and <code>ARM_LAMBDA_CONTAINER</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_LAMBDA_2GB</code>: Use up to 2 GiB memory for\n                    builds. Only available for environment type <code>LINUX_LAMBDA_CONTAINER</code> and <code>ARM_LAMBDA_CONTAINER</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_LAMBDA_4GB</code>: Use up to 4 GiB memory for\n                    builds. Only available for environment type <code>LINUX_LAMBDA_CONTAINER</code> and <code>ARM_LAMBDA_CONTAINER</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_LAMBDA_8GB</code>: Use up to 8 GiB memory for\n                    builds. Only available for environment type <code>LINUX_LAMBDA_CONTAINER</code> and <code>ARM_LAMBDA_CONTAINER</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BUILD_LAMBDA_10GB</code>: Use up to 10 GiB memory for\n                    builds. Only available for environment type <code>LINUX_LAMBDA_CONTAINER</code> and <code>ARM_LAMBDA_CONTAINER</code>.</p>\n            </li>\n         </ul>\n         <p> If you use <code>BUILD_GENERAL1_SMALL</code>: </p>\n         <ul>\n            <li>\n               <p> For environment type <code>LINUX_CONTAINER</code>, you can use up to 4 GiB\n                    memory and 2 vCPUs for builds. </p>\n            </li>\n            <li>\n               <p> For environment type <code>LINUX_GPU_CONTAINER</code>, you can use up to 16\n                    GiB memory, 4 vCPUs, and 1 NVIDIA A10G Tensor Core GPU for builds.</p>\n            </li>\n            <li>\n               <p> For environment type <code>ARM_CONTAINER</code>, you can use up to 4 GiB\n                    memory and 2 vCPUs on ARM-based processors for builds.</p>\n            </li>\n         </ul>\n         <p> If you use <code>BUILD_GENERAL1_LARGE</code>: </p>\n         <ul>\n            <li>\n               <p> For environment type <code>LINUX_CONTAINER</code>, you can use up to 16 GiB\n                    memory and 8 vCPUs for builds. </p>\n            </li>\n            <li>\n               <p> For environment type <code>LINUX_GPU_CONTAINER</code>, you can use up to 255\n                    GiB memory, 32 vCPUs, and 4 NVIDIA Tesla V100 GPUs for builds.</p>\n            </li>\n            <li>\n               <p> For environment type <code>ARM_CONTAINER</code>, you can use up to 16 GiB\n                    memory and 8 vCPUs on ARM-based processors for builds.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-env-ref-compute-types.html#environment.types\">On-demand environment types</a> \n                in the <i>CodeBuild User Guide.</i>\n         </p>", "smithy.api#required" => {}}))
    ProjectEnvironment.add_member(:compute_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeConfiguration, location_name: 'computeConfiguration', traits: {"smithy.api#documentation" => "<p>The compute configuration of the build project. This is only required if <code>computeType</code> is set to <code>ATTRIBUTE_BASED_COMPUTE</code>.</p>"}))
    ProjectEnvironment.add_member(:fleet, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectFleet, location_name: 'fleet', traits: {"smithy.api#documentation" => "<p>A ProjectFleet object to use for this build project.</p>"}))
    ProjectEnvironment.add_member(:environment_variables, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environmentVariables', traits: {"smithy.api#documentation" => "<p>A set of environment variables to make available to builds for this build\n            project.</p>"}))
    ProjectEnvironment.add_member(:privileged_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'privilegedMode', traits: {"smithy.api#documentation" => "<p>Enables running the Docker daemon inside a Docker container. Set to true only if the\n            build project is used to build Docker images. Otherwise, a build that attempts to\n            interact with the Docker daemon fails. The default setting is <code>false</code>.</p>\n         <p>You can initialize the Docker daemon during the install phase of your build by adding\n            one of the following sets of commands to the install phase of your buildspec\n            file:</p>\n         <p>If the operating system's base image is Ubuntu Linux:</p>\n         <p>\n            <code>- nohup /usr/local/bin/dockerd --host=unix:///var/run/docker.sock --host=tcp://0.0.0.0:2375 --storage-driver=overlay&</code>\n         </p>\n         <p>\n            <code>- timeout 15 sh -c \"until docker info; do echo .; sleep 1; done\"</code>\n         </p>\n         <p>If the operating system's base image is Alpine Linux and the previous command does not\n            work, add the <code>-t</code> argument to <code>timeout</code>:</p>\n         <p>\n            <code>- nohup /usr/local/bin/dockerd --host=unix:///var/run/docker.sock --host=tcp://0.0.0.0:2375 --storage-driver=overlay&</code>\n         </p>\n         <p>\n            <code>- timeout -t 15 sh -c \"until docker info; do echo .; sleep 1; done\"</code>\n         </p>"}))
    ProjectEnvironment.add_member(:certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'certificate', traits: {"smithy.api#documentation" => "<p>The ARN of the Amazon S3 bucket, path prefix, and object key that contains the PEM-encoded\n            certificate for the build project. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/create-project-cli.html#cli.environment.certificate\">certificate</a> in the\n                <i>CodeBuild User Guide</i>.</p>"}))
    ProjectEnvironment.add_member(:registry_credential, Smithy::Schema::Shapes::ShapeRef.new(shape: RegistryCredential, location_name: 'registryCredential', traits: {"smithy.api#documentation" => "<p> The credentials for access to a private registry.</p>"}))
    ProjectEnvironment.add_member(:image_pull_credentials_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ImagePullCredentialsType, location_name: 'imagePullCredentialsType', traits: {"smithy.api#documentation" => "<p> The type of credentials CodeBuild uses to pull images in your build. There are two valid\n            values: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>CODEBUILD</code> specifies that CodeBuild uses its own credentials.\n                    This requires that you modify your ECR repository policy to trust CodeBuild service principal. </p>\n            </li>\n            <li>\n               <p>\n                  <code>SERVICE_ROLE</code> specifies that CodeBuild uses your build project's service\n                    role. </p>\n            </li>\n         </ul>\n         <p> When you use a cross-account or private registry image, you must use SERVICE_ROLE\n            credentials. When you use an CodeBuild curated image, you must use CODEBUILD credentials.\n        </p>"}))
    ProjectEnvironment.add_member(:docker_server, Smithy::Schema::Shapes::ShapeRef.new(shape: DockerServer, location_name: 'dockerServer', traits: {"smithy.api#documentation" => "<p>A DockerServer object to use for this build project.</p>"}))
    ProjectEnvironment.type = Types::ProjectEnvironment
    ProjectFileSystemLocation.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemType, location_name: 'type', traits: {"smithy.api#documentation" => "<p> The type of the file system. The one supported type is <code>EFS</code>. </p>"}))
    ProjectFileSystemLocation.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'location', traits: {"smithy.api#documentation" => "<p>A string that specifies the location of the file system created by Amazon EFS. Its\n            format is <code>efs-dns-name:/directory-path</code>. You can find the DNS name of file\n            system when you view it in the Amazon EFS console. The directory path is a path to a\n            directory in the file system that CodeBuild mounts. For example, if the DNS name of a\n            file system is <code>fs-abcd1234.efs.us-west-2.amazonaws.com</code>, and its mount\n            directory is <code>my-efs-mount-directory</code>, then the <code>location</code> is\n                <code>fs-abcd1234.efs.us-west-2.amazonaws.com:/my-efs-mount-directory</code>. </p>\n         <p>The directory path in the format <code>efs-dns-name:/directory-path</code> is\n            optional. If you do not specify a directory path, the location is only the DNS name and\n            CodeBuild mounts the entire file system. </p>"}))
    ProjectFileSystemLocation.add_member(:mount_point, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'mountPoint', traits: {"smithy.api#documentation" => "<p>The location in the container where you mount the file system. </p>"}))
    ProjectFileSystemLocation.add_member(:identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'identifier', traits: {"smithy.api#documentation" => "<p>The name used to access a file system created by Amazon EFS. CodeBuild creates an\n            environment variable by appending the <code>identifier</code> in all capital letters to\n                <code>CODEBUILD_</code>. For example, if you specify <code>my_efs</code> for\n                <code>identifier</code>, a new environment variable is create named\n                <code>CODEBUILD_MY_EFS</code>. </p>\n         <p> The <code>identifier</code> is used to mount your file system. </p>"}))
    ProjectFileSystemLocation.add_member(:mount_options, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'mountOptions', traits: {"smithy.api#documentation" => "<p> The mount options for a file system created by Amazon EFS. The default mount options\n            used by CodeBuild are\n                <code>nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2</code>. For\n            more information, see <a href=\"https://docs.aws.amazon.com/efs/latest/ug/mounting-fs-nfs-mount-settings.html\">Recommended NFS Mount\n                Options</a>. </p>"}))
    ProjectFileSystemLocation.type = Types::ProjectFileSystemLocation
    ProjectFileSystemLocations.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectFileSystemLocation)
    ProjectFleet.add_member(:fleet_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'fleetArn', traits: {"smithy.api#documentation" => "<p>Specifies the compute fleet ARN for the build project.</p>"}))
    ProjectFleet.type = Types::ProjectFleet
