    ProjectSortByType.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NAME', traits: {"smithy.api#enumValue" => "NAME"}))
    ProjectSortByType.add_member(:created_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CREATED_TIME', traits: {"smithy.api#enumValue" => "CREATED_TIME"}))
    ProjectSortByType.add_member(:last_modified_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LAST_MODIFIED_TIME', traits: {"smithy.api#enumValue" => "LAST_MODIFIED_TIME"}))
    ProjectSource.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of repository that contains the source code to be built. Valid values\n            include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>BITBUCKET</code>: The source code is in a Bitbucket repository.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CODECOMMIT</code>: The source code is in an CodeCommit repository.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CODEPIPELINE</code>: The source code settings are specified in the\n                    source action of a pipeline in CodePipeline.</p>\n            </li>\n            <li>\n               <p>\n                  <code>GITHUB</code>: The source code is in a GitHub repository.</p>\n            </li>\n            <li>\n               <p>\n                  <code>GITHUB_ENTERPRISE</code>: The source code is in a GitHub Enterprise\n                    Server repository.</p>\n            </li>\n            <li>\n               <p>\n                  <code>GITLAB</code>: The source code is in a GitLab repository.</p>\n            </li>\n            <li>\n               <p>\n                  <code>GITLAB_SELF_MANAGED</code>: The source code is in a self-managed GitLab repository.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NO_SOURCE</code>: The project does not have input source code.</p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code>: The source code is in an Amazon S3 bucket.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ProjectSource.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'location', traits: {"smithy.api#documentation" => "<p>Information about the location of the source code to be built. Valid values\n            include:</p>\n         <ul>\n            <li>\n               <p>For source code settings that are specified in the source action of a pipeline\n                    in CodePipeline, <code>location</code> should not be specified. If it is specified,\n                    CodePipeline ignores it. This is because CodePipeline uses the settings in a pipeline's source\n                    action instead of this value.</p>\n            </li>\n            <li>\n               <p>For source code in an CodeCommit repository, the HTTPS clone URL to the repository\n                    that contains the source code and the buildspec file (for example,\n                        <code>https://git-codecommit.<region-ID>.amazonaws.com/v1/repos/<repo-name></code>).</p>\n            </li>\n            <li>\n               <p>For source code in an Amazon S3 input bucket, one of the following. </p>\n               <ul>\n                  <li>\n                     <p>The path to the ZIP file that contains the source code (for example,\n                                <code><bucket-name>/<path>/<object-name>.zip</code>). </p>\n                  </li>\n                  <li>\n                     <p>The path to the folder that contains the source code (for example,\n                                <code><bucket-name>/<path-to-source-code>/<folder>/</code>). </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>For source code in a GitHub repository, the HTTPS clone URL to the repository\n                    that contains the source and the buildspec file. You must connect your Amazon Web Services account \n                    to your GitHub account. Use the CodeBuild console to start creating a build\n                    project. When you use the console to connect (or reconnect) with GitHub, on the\n                    GitHub <b>Authorize application</b> page, for\n                        <b>Organization access</b>, choose <b>Request access</b> next to each repository you want to\n                    allow CodeBuild to have access to, and then choose <b>Authorize\n                        application</b>. (After you have connected to your GitHub account,\n                    you do not need to finish creating the build project. You can leave the CodeBuild\n                    console.) To instruct CodeBuild to use this connection, in the <code>source</code>\n                    object, set the <code>auth</code> object's <code>type</code> value to\n                        <code>OAUTH</code>.</p>\n            </li>\n            <li>\n               <p>For source code in an GitLab or self-managed GitLab repository, the HTTPS clone URL to the repository\n                    that contains the source and the buildspec file. You must connect your Amazon Web Services account \n                    to your GitLab account. Use the CodeBuild console to start creating a build\n                    project. When you use the console to connect (or reconnect) with GitLab, on the\n                    Connections <b>Authorize application</b> page, choose <b>Authorize</b>. Then on the CodeConnections <b>Create GitLab connection</b> page, \n                    choose <b>Connect to GitLab</b>. (After you have connected to your GitLab account,\n                    you do not need to finish creating the build project. You can leave the CodeBuild\n                    console.) To instruct CodeBuild to override the default connection and use this connection instead,\n                    set the <code>auth</code> object's <code>type</code> value to\n                    <code>CODECONNECTIONS</code> in the <code>source</code> object.</p>\n            </li>\n            <li>\n               <p>For source code in a Bitbucket repository, the HTTPS clone URL to the\n                    repository that contains the source and the buildspec file. You must connect\n                    your Amazon Web Services account to your Bitbucket account. Use the CodeBuild console to start\n                    creating a build project. When you use the console to connect (or reconnect)\n                    with Bitbucket, on the Bitbucket <b>Confirm access to your\n                        account</b> page, choose <b>Grant\n                        access</b>. (After you have connected to your Bitbucket account, you\n                    do not need to finish creating the build project. You can leave the CodeBuild\n                    console.) To instruct CodeBuild to use this connection, in the <code>source</code>\n                    object, set the <code>auth</code> object's <code>type</code> value to\n                        <code>OAUTH</code>.</p>\n            </li>\n         </ul>\n         <p>\n          If you specify <code>CODEPIPELINE</code> for the <code>Type</code> property, don't specify this \n          property. For all of the other types, you must specify <code>Location</code>.\n       </p>"}))
    ProjectSource.add_member(:git_clone_depth, Smithy::Schema::Shapes::ShapeRef.new(shape: GitCloneDepth, location_name: 'gitCloneDepth', traits: {"smithy.api#documentation" => "<p>Information about the Git clone depth for the build project.</p>"}))
    ProjectSource.add_member(:git_submodules_config, Smithy::Schema::Shapes::ShapeRef.new(shape: GitSubmodulesConfig, location_name: 'gitSubmodulesConfig', traits: {"smithy.api#documentation" => "<p> Information about the Git submodules configuration for the build project. </p>"}))
    ProjectSource.add_member(:buildspec, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'buildspec', traits: {"smithy.api#documentation" => "<p>The buildspec file declaration to use for the builds in this build project.</p>\n         <p> If this value is set, it can be either an inline buildspec definition, the path to an\n            alternate buildspec file relative to the value of the built-in\n                <code>CODEBUILD_SRC_DIR</code> environment variable, or the path to an S3 bucket.\n            The bucket must be in the same Amazon Web Services Region as the build project. Specify the buildspec\n            file using its ARN (for example,\n                <code>arn:aws:s3:::my-codebuild-sample2/buildspec.yml</code>). If this value is not\n            provided or is set to an empty string, the source code must contain a buildspec file in\n            its root directory. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-spec-ref.html#build-spec-ref-name-storage\">Buildspec File Name and Storage Location</a>. </p>"}))
    ProjectSource.add_member(:auth, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceAuth, location_name: 'auth', traits: {"smithy.api#documentation" => "<p>Information about the authorization settings for CodeBuild to access the source code to be\n            built.</p>"}))
    ProjectSource.add_member(:report_build_status, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'reportBuildStatus', traits: {"smithy.api#documentation" => "<p> Set to true to report the status of a build's start and finish to your source\n            provider. This option is valid only when your source provider is GitHub, GitHub\n            Enterprise, GitLab, GitLab Self Managed, GitLab, GitLab Self Managed, or Bitbucket. If this is set and you use a different source provider, an\n            <code>invalidInputException</code> is thrown. </p>\n         <p>To be able to report the build status to the source provider, the user associated with the source provider must\nhave write access to the repo. If the user does not have write access, the build status cannot be updated. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/access-tokens.html\">Source provider access</a> in the <i>CodeBuild User Guide</i>.</p>\n         <p>The status of a build triggered by a webhook is always reported to your source\n                provider. </p>\n         <p>If your project's builds are triggered by a webhook, you must push a\n              new commit to the repo for a change to this property to take\n              effect.</p>"}))
    ProjectSource.add_member(:build_status_config, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildStatusConfig, location_name: 'buildStatusConfig', traits: {"smithy.api#documentation" => "<p>Contains information that defines how the build project reports the build status to\n            the source provider. This option is only used when the source provider is\n                <code>GITHUB</code>, <code>GITHUB_ENTERPRISE</code>, or\n            <code>BITBUCKET</code>.</p>"}))
    ProjectSource.add_member(:insecure_ssl, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'insecureSsl', traits: {"smithy.api#documentation" => "<p>Enable this flag to ignore SSL warnings while connecting to the project source\n          code.</p>"}))
    ProjectSource.add_member(:source_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceIdentifier', traits: {"smithy.api#documentation" => "<p>An identifier for this project source. The identifier can only contain\n          alphanumeric characters and underscores, and must be less than 128 characters in length. </p>"}))
    ProjectSource.type = Types::ProjectSource
    ProjectSourceVersion.add_member(:source_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceIdentifier', traits: {"smithy.api#documentation" => "<p>An identifier for a source in the build project. The identifier can only contain\n            alphanumeric characters and underscores, and must be less than 128 characters in length. </p>", "smithy.api#required" => {}}))
    ProjectSourceVersion.add_member(:source_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceVersion', traits: {"smithy.api#documentation" => "<p>The source version for the corresponding source identifier. If specified, must be one\n          of:</p>\n         <ul>\n            <li>\n               <p>For CodeCommit: the commit ID, branch, or Git tag to use.</p>\n            </li>\n            <li>\n               <p>For GitHub: the commit ID, pull request ID, branch name, or tag name that\n                  corresponds to the version of the source code you want to build. If a pull\n                  request ID is specified, it must use the format <code>pr/pull-request-ID</code>\n                  (for example, <code>pr/25</code>). If a branch name is specified, the branch's\n                  HEAD commit ID is used. If not specified, the default branch's HEAD commit ID is\n                  used.</p>\n            </li>\n            <li>\n               <p>For GitLab: the commit ID, branch, or Git tag to use.</p>\n            </li>\n            <li>\n               <p>For Bitbucket: the commit ID, branch name, or tag name that corresponds to the\n                  version of the source code you want to build. If a branch name is specified, the\n                  branch's HEAD commit ID is used. If not specified, the default branch's HEAD\n                  commit ID is used.</p>\n            </li>\n            <li>\n               <p>For Amazon S3: the version ID of the object that represents the build input ZIP\n                  file to use.</p>\n            </li>\n         </ul>\n         <p> For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-source-version.html\">Source Version Sample\n              with CodeBuild</a> in the <i>CodeBuild User Guide</i>. </p>", "smithy.api#required" => {}}))
    ProjectSourceVersion.type = Types::ProjectSourceVersion
    ProjectSources.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSource)
    ProjectVisibilityType.add_member(:public_read, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PUBLIC_READ', traits: {"smithy.api#enumValue" => "PUBLIC_READ"}))
    ProjectVisibilityType.add_member(:private, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PRIVATE', traits: {"smithy.api#enumValue" => "PRIVATE"}))
    Projects.member = Smithy::Schema::Shapes::ShapeRef.new(shape: Project)
    ProxyConfiguration.add_member(:default_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetProxyRuleBehavior, location_name: 'defaultBehavior', traits: {"smithy.api#documentation" => "<p>The default behavior of outgoing traffic.</p>"}))
    ProxyConfiguration.add_member(:ordered_proxy_rules, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetProxyRules, location_name: 'orderedProxyRules', traits: {"smithy.api#documentation" => "<p>An array of <code>FleetProxyRule</code> objects that represent the specified destination domains or IPs to allow or deny network access control to.</p>"}))
    ProxyConfiguration.type = Types::ProxyConfiguration
    PullRequestBuildApproverRole.add_member(:github_read, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITHUB_READ', traits: {"smithy.api#enumValue" => "GITHUB_READ"}))
    PullRequestBuildApproverRole.add_member(:github_triage, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITHUB_TRIAGE', traits: {"smithy.api#enumValue" => "GITHUB_TRIAGE"}))
    PullRequestBuildApproverRole.add_member(:github_write, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITHUB_WRITE', traits: {"smithy.api#enumValue" => "GITHUB_WRITE"}))
    PullRequestBuildApproverRole.add_member(:github_maintain, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITHUB_MAINTAIN', traits: {"smithy.api#enumValue" => "GITHUB_MAINTAIN"}))
    PullRequestBuildApproverRole.add_member(:github_admin, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITHUB_ADMIN', traits: {"smithy.api#enumValue" => "GITHUB_ADMIN"}))
    PullRequestBuildApproverRole.add_member(:gitlab_guest, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITLAB_GUEST', traits: {"smithy.api#enumValue" => "GITLAB_GUEST"}))
    PullRequestBuildApproverRole.add_member(:gitlab_planner, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITLAB_PLANNER', traits: {"smithy.api#enumValue" => "GITLAB_PLANNER"}))
    PullRequestBuildApproverRole.add_member(:gitlab_reporter, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GITLAB_REPORTER', traits: {"smithy.api#enumValue" => "GITLAB_REPORTER"}))
