    StartBuildBatchInput.add_member(:git_clone_depth_override, Smithy::Schema::Shapes::ShapeRef.new(shape: GitCloneDepth, location_name: 'gitCloneDepthOverride', traits: {"smithy.api#documentation" => "<p>The user-defined depth of history, with a minimum value of 0, that overrides, for this\n        batch build only, any previous depth of history defined in the batch build project.</p>"}))
    StartBuildBatchInput.add_member(:git_submodules_config_override, Smithy::Schema::Shapes::ShapeRef.new(shape: GitSubmodulesConfig, location_name: 'gitSubmodulesConfigOverride', traits: {"smithy.api#documentation" => "<p>A <code>GitSubmodulesConfig</code> object that overrides the Git submodules configuration\n            for this batch build.</p>"}))
    StartBuildBatchInput.add_member(:buildspec_override, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'buildspecOverride', traits: {"smithy.api#documentation" => "<p>A buildspec file declaration that overrides, for this build only, the latest one\n        already defined in the build project.</p>\n         <p>If this value is set, it can be either an inline buildspec definition, the path to an\n        alternate buildspec file relative to the value of the built-in\n        <code>CODEBUILD_SRC_DIR</code> environment variable, or the path to an S3 bucket.\n        The bucket must be in the same Amazon Web Services Region as the build project. Specify the buildspec\n        file using its ARN (for example,\n        <code>arn:aws:s3:::my-codebuild-sample2/buildspec.yml</code>). If this value is not\n        provided or is set to an empty string, the source code must contain a buildspec file in\n        its root directory. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-spec-ref.html#build-spec-ref-name-storage\">Buildspec File Name and Storage Location</a>. </p>"}))
    StartBuildBatchInput.add_member(:insecure_ssl_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'insecureSslOverride', traits: {"smithy.api#documentation" => "<p>Enable this flag to override the insecure SSL setting that is specified in the batch build\n        project. The insecure SSL setting determines whether to ignore SSL warnings while\n        connecting to the project source code. This override applies only if the build's source\n        is GitHub Enterprise.</p>"}))
    StartBuildBatchInput.add_member(:report_build_batch_status_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'reportBuildBatchStatusOverride', traits: {"smithy.api#documentation" => "<p>Set to <code>true</code> to report to your source provider the status of a batch build's\n            start and completion. If you use this option with a source provider other than GitHub,\n            GitHub Enterprise, or Bitbucket, an <code>invalidInputException</code> is thrown. </p>\n         <note>\n            <p>The status of a build triggered by a webhook is always reported to your source\n          provider. </p>\n         </note>"}))
