    StartBuildBatchInput.add_member(:compute_type_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeType, location_name: 'computeTypeOverride', traits: {"smithy.api#documentation" => "<p>The name of a compute type for this batch build that overrides the one specified in the\n        batch build project.</p>"}))
