    StartBuildBatchInput.add_member(:cache_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectCache, location_name: 'cacheOverride', traits: {"smithy.api#documentation" => "<p>A <code>ProjectCache</code> object that specifies cache overrides.</p>"}))
