    StartBuildBatchInput.add_member(:privileged_mode_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'privilegedModeOverride', traits: {"smithy.api#documentation" => "<p>Enable this flag to override privileged mode in the batch build project.</p>"}))
    StartBuildBatchInput.add_member(:build_timeout_in_minutes_override, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildTimeOut, location_name: 'buildTimeoutInMinutesOverride', traits: {"smithy.api#documentation" => "<p>Overrides the build timeout specified in the batch build project.</p>"}))
    StartBuildBatchInput.add_member(:queued_timeout_in_minutes_override, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeOut, location_name: 'queuedTimeoutInMinutesOverride', traits: {"smithy.api#documentation" => "<p>The number of minutes a batch build is allowed to be queued before it times out.</p>"}))
