    StartBuildBatchInput.add_member(:idempotency_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'idempotencyToken', traits: {"smithy.api#documentation" => "<p>A unique, case sensitive identifier you provide to ensure the idempotency of the\n                <code>StartBuildBatch</code> request. The token is included in the\n                <code>StartBuildBatch</code> request and is valid for five minutes. If you repeat\n            the <code>StartBuildBatch</code> request with the same token, but change a parameter,\n            CodeBuild returns a parameter mismatch error.</p>"}))
    StartBuildBatchInput.add_member(:logs_config_override, Smithy::Schema::Shapes::ShapeRef.new(shape: LogsConfig, location_name: 'logsConfigOverride', traits: {"smithy.api#documentation" => "<p>A <code>LogsConfig</code> object that override the log settings defined in the batch build\n            project.</p>"}))
    StartBuildBatchInput.add_member(:registry_credential_override, Smithy::Schema::Shapes::ShapeRef.new(shape: RegistryCredential, location_name: 'registryCredentialOverride', traits: {"smithy.api#documentation" => "<p>A <code>RegistryCredential</code> object that overrides credentials for access to a\n            private registry.</p>"}))
    StartBuildBatchInput.add_member(:image_pull_credentials_type_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ImagePullCredentialsType, location_name: 'imagePullCredentialsTypeOverride', traits: {"smithy.api#documentation" => "<p>The type of credentials CodeBuild uses to pull images in your batch build. There are two valid\n        values: </p>\n         <dl>\n            <dt>CODEBUILD</dt>\n            <dd>\n               <p>Specifies that CodeBuild uses its own credentials. This requires that you\n                        modify your ECR repository policy to trust CodeBuild's service principal.</p>\n            </dd>\n            <dt>SERVICE_ROLE</dt>\n            <dd>\n               <p>Specifies that CodeBuild uses your build project's service role. </p>\n            </dd>\n         </dl>\n         <p>When using a cross-account or private registry image, you must use\n                <code>SERVICE_ROLE</code> credentials. When using an CodeBuild curated image,\n            you must use <code>CODEBUILD</code> credentials. </p>"}))
    StartBuildBatchInput.add_member(:build_batch_config_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectBuildBatchConfig, location_name: 'buildBatchConfigOverride', traits: {"smithy.api#documentation" => "<p>A <code>BuildBatchConfigOverride</code> object that contains batch build configuration\n            overrides.</p>"}))
    StartBuildBatchInput.add_member(:debug_session_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'debugSessionEnabled', traits: {"smithy.api#documentation" => "<p>Specifies if session debugging is enabled for this batch build. For more information, see\n  <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/session-manager.html\">Viewing a running build in Session Manager</a>. Batch session debugging is not supported for matrix batch builds.</p>"}))
