    StartBuildInput.add_member(:project_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'projectName', traits: {"smithy.api#documentation" => "<p>The name of the CodeBuild build project to start running a build.</p>", "smithy.api#required" => {}}))
    StartBuildInput.add_member(:secondary_sources_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSources, location_name: 'secondarySourcesOverride', traits: {"smithy.api#documentation" => "<p> An array of <code>ProjectSource</code> objects. </p>"}))
    StartBuildInput.add_member(:secondary_sources_version_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSecondarySourceVersions, location_name: 'secondarySourcesVersionOverride', traits: {"smithy.api#documentation" => "<p> An array of <code>ProjectSourceVersion</code> objects that specify one or more\n            versions of the project's secondary sources to be used for this build only. </p>"}))
    StartBuildInput.add_member(:source_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceVersion', traits: {"smithy.api#documentation" => "<p>The version of the build input to be built, for this build only. If not specified,\n            the latest version is used. If specified, the contents depends on the source\n            provider:</p>\n         <dl>\n            <dt>CodeCommit</dt>\n            <dd>\n               <p>The commit ID, branch, or Git tag to use.</p>\n            </dd>\n            <dt>GitHub</dt>\n            <dd>\n               <p>The commit ID, pull request ID, branch name, or tag name that corresponds\n                        to the version of the source code you want to build. If a pull request ID is\n                        specified, it must use the format <code>pr/pull-request-ID</code> (for\n                        example <code>pr/25</code>). If a branch name is specified, the branch's\n                        HEAD commit ID is used. If not specified, the default branch's HEAD commit\n                        ID is used.</p>\n            </dd>\n            <dt>GitLab</dt>\n            <dd>\n               <p>The commit ID, branch, or Git tag to use.</p>\n            </dd>\n            <dt>Bitbucket</dt>\n            <dd>\n               <p>The commit ID, branch name, or tag name that corresponds to the version of\n                        the source code you want to build. If a branch name is specified, the\n                        branch's HEAD commit ID is used. If not specified, the default branch's HEAD\n                        commit ID is used.</p>\n            </dd>\n            <dt>Amazon S3</dt>\n            <dd>\n               <p>The version ID of the object that represents the build input ZIP file to\n                        use.</p>\n            </dd>\n         </dl>\n         <p>If <code>sourceVersion</code> is specified at the project level, then this\n            <code>sourceVersion</code> (at the build level) takes precedence. </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-source-version.html\">Source Version Sample\n            with CodeBuild</a> in the <i>CodeBuild User Guide</i>. </p>"}))
    StartBuildInput.add_member(:artifacts_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectArtifacts, location_name: 'artifactsOverride', traits: {"smithy.api#documentation" => "<p>Build output artifact settings that override, for this build only, the latest ones\n            already defined in the build project.</p>"}))
    StartBuildInput.add_member(:secondary_artifacts_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectArtifactsList, location_name: 'secondaryArtifactsOverride', traits: {"smithy.api#documentation" => "<p> An array of <code>ProjectArtifacts</code> objects. </p>"}))
    StartBuildInput.add_member(:environment_variables_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environmentVariablesOverride', traits: {"smithy.api#documentation" => "<p>A set of environment variables that overrides, for this build only, the latest ones\n            already defined in the build project.</p>"}))
    StartBuildInput.add_member(:source_type_override, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceType, location_name: 'sourceTypeOverride', traits: {"smithy.api#documentation" => "<p>A source input type, for this build, that overrides the source input defined in the\n            build project.</p>"}))
    StartBuildInput.add_member(:source_location_override, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceLocationOverride', traits: {"smithy.api#documentation" => "<p>A location that overrides, for this build, the source location for the one defined in\n            the build project.</p>"}))
    StartBuildInput.add_member(:source_auth_override, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceAuth, location_name: 'sourceAuthOverride', traits: {"smithy.api#documentation" => "<p>An authorization type for this build that overrides the one defined in the build\n            project. This override applies only if the build project's source is BitBucket, GitHub, \n            GitLab, or GitLab Self Managed.</p>"}))
    StartBuildInput.add_member(:git_clone_depth_override, Smithy::Schema::Shapes::ShapeRef.new(shape: GitCloneDepth, location_name: 'gitCloneDepthOverride', traits: {"smithy.api#documentation" => "<p>The user-defined depth of history, with a minimum value of 0, that overrides, for this\n            build only, any previous depth of history defined in the build project.</p>"}))
    StartBuildInput.add_member(:git_submodules_config_override, Smithy::Schema::Shapes::ShapeRef.new(shape: GitSubmodulesConfig, location_name: 'gitSubmodulesConfigOverride', traits: {"smithy.api#documentation" => "<p> Information about the Git submodules configuration for this build of an CodeBuild build\n            project. </p>"}))
    StartBuildInput.add_member(:buildspec_override, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'buildspecOverride', traits: {"smithy.api#documentation" => "<p>A buildspec file declaration that overrides the latest one defined \n            in the build project, for this build only. The buildspec defined on the project is not changed.</p>\n         <p>If this value is set, it can be either an inline buildspec definition, the path to an\n            alternate buildspec file relative to the value of the built-in\n                <code>CODEBUILD_SRC_DIR</code> environment variable, or the path to an S3 bucket.\n            The bucket must be in the same Amazon Web Services Region as the build project. Specify the buildspec\n            file using its ARN (for example,\n                <code>arn:aws:s3:::my-codebuild-sample2/buildspec.yml</code>). If this value is not\n            provided or is set to an empty string, the source code must contain a buildspec file in\n            its root directory. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/build-spec-ref.html#build-spec-ref-name-storage\">Buildspec File Name and Storage Location</a>.</p>\n         <note>\n            <p>Since this property allows you to change the build commands that will run in the container, \n            you should note that an IAM principal with the ability to call this API and set this parameter \n            can override the default settings. Moreover, we encourage that you use a trustworthy buildspec location \n            like a file in your source repository or a Amazon S3 bucket. Alternatively, you can restrict overrides \n            to the buildspec by using a condition key: <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/action-context-keys.html#action-context-keys-example-overridebuildspec.html\">Prevent unauthorized modifications to project buildspec</a>.</p>\n         </note>"}))
    StartBuildInput.add_member(:insecure_ssl_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'insecureSslOverride', traits: {"smithy.api#documentation" => "<p>Enable this flag to override the insecure SSL setting that is specified in the build\n            project. The insecure SSL setting determines whether to ignore SSL warnings while\n            connecting to the project source code. This override applies only if the build's source\n            is GitHub Enterprise.</p>"}))
    StartBuildInput.add_member(:report_build_status_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'reportBuildStatusOverride', traits: {"smithy.api#documentation" => "<p> Set to true to report to your source provider the status of a build's start and\n            completion. If you use this option with a source provider other than GitHub, GitHub\n            Enterprise, GitLab, GitLab Self Managed, or Bitbucket, an <code>invalidInputException</code> is thrown. </p>\n         <p>To be able to report the build status to the source provider, the user associated with the source provider must\nhave write access to the repo. If the user does not have write access, the build status cannot be updated. For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/access-tokens.html\">Source provider access</a> in the <i>CodeBuild User Guide</i>.</p>\n         <note>\n            <p> The status of a build triggered by a webhook is always reported to your source\n                provider. </p>\n         </note>"}))
    StartBuildInput.add_member(:build_status_config_override, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildStatusConfig, location_name: 'buildStatusConfigOverride', traits: {"smithy.api#documentation" => "<p>Contains information that defines how the build project reports the build status to\n            the source provider. This option is only used when the source provider is\n                <code>GITHUB</code>, <code>GITHUB_ENTERPRISE</code>, or\n            <code>BITBUCKET</code>.</p>"}))
    StartBuildInput.add_member(:environment_type_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentType, location_name: 'environmentTypeOverride', traits: {"smithy.api#documentation" => "<p>A container type for this build that overrides the one specified in the build\n            project.</p>"}))
    StartBuildInput.add_member(:image_override, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'imageOverride', traits: {"smithy.api#documentation" => "<p>The name of an image for this build that overrides the one specified in the build\n            project.</p>"}))
    StartBuildInput.add_member(:compute_type_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeType, location_name: 'computeTypeOverride', traits: {"smithy.api#documentation" => "<p>The name of a compute type for this build that overrides the one specified in the\n            build project.</p>"}))
    StartBuildInput.add_member(:certificate_override, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'certificateOverride', traits: {"smithy.api#documentation" => "<p>The name of a certificate for this build that overrides the one specified in the build\n            project.</p>"}))
    StartBuildInput.add_member(:cache_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectCache, location_name: 'cacheOverride', traits: {"smithy.api#documentation" => "<p>A ProjectCache object specified for this build that overrides the one defined in the\n            build project.</p>"}))
    StartBuildInput.add_member(:service_role_override, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'serviceRoleOverride', traits: {"smithy.api#documentation" => "<p>The name of a service role for this build that overrides the one specified in the\n            build project.</p>"}))
    StartBuildInput.add_member(:privileged_mode_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'privilegedModeOverride', traits: {"smithy.api#documentation" => "<p>Enable this flag to override privileged mode in the build project.</p>"}))
    StartBuildInput.add_member(:timeout_in_minutes_override, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildTimeOut, location_name: 'timeoutInMinutesOverride', traits: {"smithy.api#documentation" => "<p>The number of build timeout minutes, from 5 to 2160 (36 hours), that overrides, for this\n            build only, the latest setting already defined in the build project.</p>"}))
    StartBuildInput.add_member(:queued_timeout_in_minutes_override, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeOut, location_name: 'queuedTimeoutInMinutesOverride', traits: {"smithy.api#documentation" => "<p> The number of minutes a build is allowed to be queued before it times out. </p>"}))
    StartBuildInput.add_member(:encryption_key_override, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'encryptionKeyOverride', traits: {"smithy.api#documentation" => "<p>The Key Management Service customer master key (CMK) that overrides the one specified in the build\n            project. The CMK key encrypts the build output artifacts.</p>\n         <note>\n            <p> You can use a cross-account KMS key to encrypt the build output artifacts if your\n                service role has permission to that key. </p>\n         </note>\n         <p>You can specify either the Amazon Resource Name (ARN) of the CMK or, if available, the CMK's alias (using\n            the format <code>alias/<alias-name></code>).</p>"}))
    StartBuildInput.add_member(:idempotency_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'idempotencyToken', traits: {"smithy.api#documentation" => "<p>A unique, case sensitive identifier you provide to ensure the idempotency of the\n            StartBuild request. The token is included in the StartBuild request and is valid for 5\n            minutes. If you repeat the StartBuild request with the same token, but change a\n            parameter, CodeBuild returns a parameter mismatch error. </p>"}))
    StartBuildInput.add_member(:logs_config_override, Smithy::Schema::Shapes::ShapeRef.new(shape: LogsConfig, location_name: 'logsConfigOverride', traits: {"smithy.api#documentation" => "<p> Log settings for this build that override the log settings defined in the build\n            project. </p>"}))
    StartBuildInput.add_member(:registry_credential_override, Smithy::Schema::Shapes::ShapeRef.new(shape: RegistryCredential, location_name: 'registryCredentialOverride', traits: {"smithy.api#documentation" => "<p> The credentials for access to a private registry. </p>"}))
    StartBuildInput.add_member(:image_pull_credentials_type_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ImagePullCredentialsType, location_name: 'imagePullCredentialsTypeOverride', traits: {"smithy.api#documentation" => "<p>The type of credentials CodeBuild uses to pull images in your build. There are two valid\n            values: </p>\n         <dl>\n            <dt>CODEBUILD</dt>\n            <dd>\n               <p>Specifies that CodeBuild uses its own credentials. This requires that you\n                        modify your ECR repository policy to trust CodeBuild's service principal.</p>\n            </dd>\n            <dt>SERVICE_ROLE</dt>\n            <dd>\n               <p>Specifies that CodeBuild uses your build project's service role. </p>\n            </dd>\n         </dl>\n         <p>When using a cross-account or private registry image, you must use\n            <code>SERVICE_ROLE</code> credentials. When using an CodeBuild curated image,\n            you must use <code>CODEBUILD</code> credentials. </p>"}))
    StartBuildInput.add_member(:debug_session_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'debugSessionEnabled', traits: {"smithy.api#documentation" => "<p>Specifies if session debugging is enabled for this build. For more information, see\n                <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/session-manager.html\">Viewing a running build in Session Manager</a>.</p>"}))
    StartBuildInput.add_member(:fleet_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectFleet, location_name: 'fleetOverride', traits: {"smithy.api#documentation" => "<p>A ProjectFleet object specified for this build that overrides the one defined in the\n            build project.</p>"}))
    StartBuildInput.add_member(:auto_retry_limit_override, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'autoRetryLimitOverride', traits: {"smithy.api#documentation" => "<p>The maximum number of additional automatic retries after a failed build. For example, if the \n            auto-retry limit is set to 2, CodeBuild will call the <code>RetryBuild</code> API to automatically \n            retry your build for up to 2 additional times.</p>"}))
