    TestCaseFilter.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status used to filter test cases. A <code>TestCaseFilter</code> can have one\n            status. Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SUCCEEDED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>SKIPPED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>UNKNOWN</code>\n               </p>\n            </li>\n         </ul>"}))
    TestCaseFilter.add_member(:keyword, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'keyword', traits: {"smithy.api#documentation" => "<p>A keyword that is used to filter on the <code>name</code> or the <code>prefix</code>\n            of the test cases. Only test cases where the keyword is a substring of the\n                <code>name</code> or the <code>prefix</code> will be returned.</p>"}))
