    UpdateProjectInput.add_member(:source, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSource, location_name: 'source', traits: {"smithy.api#documentation" => "<p>Information to be changed about the build input source code for the build\n    project.</p>"}))
    UpdateProjectInput.add_member(:secondary_sources, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSources, location_name: 'secondarySources', traits: {"smithy.api#documentation" => "<p> An array of <code>ProjectSource</code> objects. </p>"}))
    UpdateProjectInput.add_member(:source_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceVersion', traits: {"smithy.api#documentation" => "<p> A version of the build input to be built for this project. If not specified, the\n    latest version is used. If specified, it must be one of: </p>\n         <ul>\n            <li>\n               <p>For CodeCommit: the commit ID, branch, or Git tag to use.</p>\n            </li>\n            <li>\n               <p>For GitHub: the commit ID, pull request ID, branch name, or tag name that\n            corresponds to the version of the source code you want to build. If a pull\n            request ID is specified, it must use the format <code>pr/pull-request-ID</code>\n            (for example <code>pr/25</code>). If a branch name is specified, the branch's\n            HEAD commit ID is used. If not specified, the default branch's HEAD commit ID is\n            used.</p>\n            </li>\n            <li>\n               <p>For GitLab: the commit ID, branch, or Git tag to use.</p>\n            </li>\n            <li>\n               <p>For Bitbucket: the commit ID, branch name, or tag name that corresponds to the\n            version of the source code you want to build. If a branch name is specified, the\n            branch's HEAD commit ID is used. If not specified, the default branch's HEAD\n            commit ID is used.</p>\n            </li>\n            <li>\n               <p>For Amazon S3: the version ID of the object that represents the build input ZIP\n            file to use.</p>\n            </li>\n         </ul>\n         <p> If <code>sourceVersion</code> is specified at the build level, then that version\n    takes precedence over this <code>sourceVersion</code> (at the project level). </p>\n         <p> For more information, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-source-version.html\">Source Version Sample\n        with CodeBuild</a> in the <i>CodeBuild User Guide</i>. \n    </p>"}))
    UpdateProjectInput.add_member(:secondary_source_versions, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectSecondarySourceVersions, location_name: 'secondarySourceVersions', traits: {"smithy.api#documentation" => "<p> An array of <code>ProjectSourceVersion</code> objects. If\n      <code>secondarySourceVersions</code> is specified at the build level, then they take\n    over these <code>secondarySourceVersions</code> (at the project level). </p>"}))
    UpdateProjectInput.add_member(:artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectArtifacts, location_name: 'artifacts', traits: {"smithy.api#documentation" => "<p>Information to be changed about the build output artifacts for the build\n        project.</p>"}))
    UpdateProjectInput.add_member(:secondary_artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectArtifactsList, location_name: 'secondaryArtifacts', traits: {"smithy.api#documentation" => "<p> An array of <code>ProjectArtifact</code> objects. </p>"}))
    UpdateProjectInput.add_member(:cache, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectCache, location_name: 'cache', traits: {"smithy.api#documentation" => "<p>Stores recently used information so that it can be quickly accessed at a later\n      time.</p>"}))
    UpdateProjectInput.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectEnvironment, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>Information to be changed about the build environment for the build project.</p>"}))
    UpdateProjectInput.add_member(:service_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'serviceRole', traits: {"smithy.api#documentation" => "<p>The replacement ARN of the IAM role that enables CodeBuild to interact with dependent\n    Amazon Web Services services on behalf of the Amazon Web Services account.</p>"}))
    UpdateProjectInput.add_member(:timeout_in_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildTimeOut, location_name: 'timeoutInMinutes', traits: {"smithy.api#documentation" => "<p>The replacement value in minutes, from 5 to 2160 (36 hours), for CodeBuild to wait before\n      timing out any related build that did not get marked as completed.</p>"}))
    UpdateProjectInput.add_member(:queued_timeout_in_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeOut, location_name: 'queuedTimeoutInMinutes', traits: {"smithy.api#documentation" => "<p> The number of minutes a build is allowed to be queued before it times out. </p>"}))
    UpdateProjectInput.add_member(:encryption_key, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'encryptionKey', traits: {"smithy.api#documentation" => "<p>The Key Management Service customer master key (CMK) to be used for encrypting the build output\n    artifacts.</p>\n         <note>\n            <p> You can use a cross-account KMS key to encrypt the build output artifacts if your\n        service role has permission to that key. </p>\n         </note>\n         <p>You can specify either the Amazon Resource Name (ARN) of the CMK or, if available, the CMK's alias (using\n    the format <code>alias/<alias-name></code>).\n    </p>"}))
    UpdateProjectInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>An updated list of tag key and value pairs associated with this build project.</p>\n         <p>These tags are available for use by Amazon Web Services services that support CodeBuild build project\n      tags.</p>"}))
    UpdateProjectInput.add_member(:vpc_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcConfig, location_name: 'vpcConfig', traits: {"smithy.api#documentation" => "<p>VpcConfig enables CodeBuild to access resources in an Amazon VPC.</p>"}))
    UpdateProjectInput.add_member(:badge_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'badgeEnabled', traits: {"smithy.api#documentation" => "<p>Set this to true to generate a publicly accessible URL for your project's build\n      badge.</p>"}))
    UpdateProjectInput.add_member(:logs_config, Smithy::Schema::Shapes::ShapeRef.new(shape: LogsConfig, location_name: 'logsConfig', traits: {"smithy.api#documentation" => "<p> Information about logs for the build project. A project can create logs in CloudWatch Logs,\n    logs in an S3 bucket, or both. </p>"}))
    UpdateProjectInput.add_member(:file_system_locations, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectFileSystemLocations, location_name: 'fileSystemLocations', traits: {"smithy.api#documentation" => "<p>\n      An array of <code>ProjectFileSystemLocation</code> objects for a CodeBuild build project. A <code>ProjectFileSystemLocation</code> object \n      specifies the <code>identifier</code>, <code>location</code>, <code>mountOptions</code>, \n      <code>mountPoint</code>, and <code>type</code> of a file system created using Amazon Elastic File System.\n  </p>"}))
    UpdateProjectInput.add_member(:build_batch_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProjectBuildBatchConfig, location_name: 'buildBatchConfig'))
    UpdateProjectInput.add_member(:concurrent_build_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'concurrentBuildLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of concurrent builds that are allowed for this project.</p>\n         <p>New builds are only started if the current number of builds is less than or equal to this limit. \n  If the current build count meets this limit, new builds are throttled and are not run.</p>\n         <p>To remove this limit, set this value to -1.</p>"}))
    UpdateProjectInput.add_member(:auto_retry_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperInt, location_name: 'autoRetryLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of additional automatic retries after a failed build. For example, if the \n      auto-retry limit is set to 2, CodeBuild will call the <code>RetryBuild</code> API to automatically \n      retry your build for up to 2 additional times.</p>"}))
