    UpdateReportGroupInput.add_member(:export_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ReportExportConfig, location_name: 'exportConfig', traits: {"smithy.api#documentation" => "<p>\n      Used to specify an updated export type. Valid values are:\n    </p>\n         <ul>\n            <li>\n               <p>\n                  <code>S3</code>: The report results are exported to an S3 bucket.\n        </p>\n            </li>\n            <li>\n               <p>\n                  <code>NO_EXPORT</code>: The report results are not exported.\n        </p>\n            </li>\n         </ul>"}))
