    UpdateWebhookInput.add_member(:branch_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'branchFilter', traits: {"smithy.api#documentation" => "<p>A regular expression used to determine which repository branches are built when a\n      webhook is triggered. If the name of a branch matches the regular expression, then it is\n      built. If <code>branchFilter</code> is empty, then all branches are built.</p>\n         <note>\n            <p> It is recommended that you use <code>filterGroups</code> instead of\n        <code>branchFilter</code>. </p>\n         </note>"}))
    UpdateWebhookInput.add_member(:rotate_secret, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'rotateSecret', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p> A boolean value that specifies whether the associated GitHub repository's secret\n      token should be updated. If you use Bitbucket for your repository,\n      <code>rotateSecret</code> is ignored. </p>"}))
    UpdateWebhookInput.add_member(:filter_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterGroups, location_name: 'filterGroups', traits: {"smithy.api#documentation" => "<p> An array of arrays of <code>WebhookFilter</code> objects used to determine if a\n      webhook event can trigger a build. A filter group must contain at least one\n      <code>EVENT</code>\n            <code>WebhookFilter</code>. </p>"}))
    UpdateWebhookInput.add_member(:build_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WebhookBuildType, location_name: 'buildType', traits: {"smithy.api#documentation" => "<p>Specifies the type of build this webhook will trigger.</p>\n         <note>\n            <p>\n               <code>RUNNER_BUILDKITE_BUILD</code> is only available for <code>NO_SOURCE</code> source type projects \n        configured for Buildkite runner builds. For more information about CodeBuild-hosted Buildkite runner builds, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-runner-buildkite.html\">Tutorial: Configure a CodeBuild-hosted Buildkite runner</a> in the <i>CodeBuild\n        user guide</i>.</p>\n         </note>"}))
    UpdateWebhookInput.add_member(:pull_request_build_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PullRequestBuildPolicy, location_name: 'pullRequestBuildPolicy', traits: {"smithy.api#documentation" => "<p>A PullRequestBuildPolicy object that defines comment-based approval requirements for triggering builds on pull requests. This policy helps control when automated builds are executed based on contributor permissions and approval workflows.</p>"}))
    UpdateWebhookInput.type = Types::UpdateWebhookInput
