    UpdateWebhookOutput.type = Types::UpdateWebhookOutput
    VpcConfig.add_member(:vpc_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'vpcId', traits: {"smithy.api#documentation" => "<p>The ID of the Amazon VPC.</p>"}))
    VpcConfig.add_member(:subnets, Smithy::Schema::Shapes::ShapeRef.new(shape: Subnets, location_name: 'subnets', traits: {"smithy.api#documentation" => "<p>A list of one or more subnet IDs in your Amazon VPC.</p>"}))
    VpcConfig.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIds, location_name: 'securityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of one or more security groups IDs in your Amazon VPC.</p>"}))
    VpcConfig.type = Types::VpcConfig
    Webhook.add_member(:url, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'url', traits: {"smithy.api#documentation" => "<p>The URL to the webhook.</p>"}))
    Webhook.add_member(:payload_url, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'payloadUrl', traits: {"smithy.api#documentation" => "<p>The CodeBuild endpoint where webhook events are sent.</p>"}))
    Webhook.add_member(:secret, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'secret', traits: {"smithy.api#documentation" => "<p>The secret token of the associated repository. </p>\n         <note>\n            <p>A Bitbucket webhook does not support <code>secret</code>. </p>\n         </note>"}))
    Webhook.add_member(:branch_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'branchFilter', traits: {"smithy.api#documentation" => "<p>A regular expression used to determine which repository branches are built when a\n      webhook is triggered. If the name of a branch matches the regular expression, then it is\n      built. If <code>branchFilter</code> is empty, then all branches are built.</p>\n         <note>\n            <p>It is recommended that you use <code>filterGroups</code> instead of\n        <code>branchFilter</code>. </p>\n         </note>"}))
    Webhook.add_member(:filter_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterGroups, location_name: 'filterGroups', traits: {"smithy.api#documentation" => "<p>An array of arrays of <code>WebhookFilter</code> objects used to determine which\n      webhooks are triggered. At least one <code>WebhookFilter</code> in the array must\n      specify <code>EVENT</code> as its <code>type</code>. </p>\n         <p>For a build to be triggered, at least one filter group in the\n      <code>filterGroups</code> array must pass. For a filter group to pass, each of its\n      filters must pass. </p>"}))
    Webhook.add_member(:build_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WebhookBuildType, location_name: 'buildType', traits: {"smithy.api#documentation" => "<p>Specifies the type of build this webhook will trigger.</p>\n         <note>\n            <p>\n               <code>RUNNER_BUILDKITE_BUILD</code> is only available for <code>NO_SOURCE</code> source type projects \n        configured for Buildkite runner builds. For more information about CodeBuild-hosted Buildkite runner builds, see <a href=\"https://docs.aws.amazon.com/codebuild/latest/userguide/sample-runner-buildkite.html\">Tutorial: Configure a CodeBuild-hosted Buildkite runner</a> in the <i>CodeBuild\n        user guide</i>.</p>\n         </note>"}))
    Webhook.add_member(:manual_creation, Smithy::Schema::Shapes::ShapeRef.new(shape: WrapperBoolean, location_name: 'manualCreation', traits: {"smithy.api#documentation" => "<p>If manualCreation is true, CodeBuild doesn't create a webhook in GitHub and instead returns <code>payloadUrl</code> and \n      <code>secret</code> values for the webhook. The <code>payloadUrl</code> and <code>secret</code> values in the output can \n      be used to manually create a webhook within GitHub.</p>\n         <note>\n            <p>manualCreation is only available for GitHub webhooks.</p>\n         </note>"}))
    Webhook.add_member(:last_modified_secret, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'lastModifiedSecret', traits: {"smithy.api#documentation" => "<p>A timestamp that indicates the last time a repository's secret token was modified.\n    </p>"}))
    Webhook.add_member(:scope_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ScopeConfiguration, location_name: 'scopeConfiguration', traits: {"smithy.api#documentation" => "<p>The scope configuration for global or organization webhooks.</p>\n         <note>\n            <p>Global or organization webhooks are only available for GitHub and Github Enterprise webhooks.</p>\n         </note>"}))
    Webhook.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: WebhookStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status of the webhook. Valid values include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CREATING</code>: The webhook is being created.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CREATE_FAILED</code>: The webhook has failed to create.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ACTIVE</code>: The webhook has succeeded and is active.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code>: The webhook is being deleted.</p>\n            </li>\n         </ul>"}))
    Webhook.add_member(:status_message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'statusMessage', traits: {"smithy.api#documentation" => "<p>A message associated with the status of a webhook.</p>"}))
    Webhook.add_member(:pull_request_build_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PullRequestBuildPolicy, location_name: 'pullRequestBuildPolicy'))
    Webhook.type = Types::Webhook
    WebhookBuildType.add_member(:build, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BUILD', traits: {"smithy.api#enumValue" => "BUILD"}))
    WebhookBuildType.add_member(:build_batch, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BUILD_BATCH', traits: {"smithy.api#enumValue" => "BUILD_BATCH"}))
    WebhookBuildType.add_member(:runner_buildkite_build, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RUNNER_BUILDKITE_BUILD', traits: {"smithy.api#enumValue" => "RUNNER_BUILDKITE_BUILD"}))
    WebhookFilter.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: WebhookFilterType, location_name: 'type', traits: {"smithy.api#documentation" => "<p> The type of webhook filter. There are 11 webhook filter types: <code>EVENT</code>,\n                <code>ACTOR_ACCOUNT_ID</code>, <code>HEAD_REF</code>, <code>BASE_REF</code>,\n            <code>FILE_PATH</code>, <code>COMMIT_MESSAGE</code>, <code>TAG_NAME</code>, <code>RELEASE_NAME</code>, \n            <code>REPOSITORY_NAME</code>, <code>ORGANIZATION_NAME</code>, \n            and <code>WORKFLOW_NAME</code>. </p>\n         <ul>\n            <li>\n               <p>\n                    EVENT\n                </p>\n               <ul>\n                  <li>\n                     <p> A webhook event triggers a build when the provided <code>pattern</code>\n                            matches one of nine event types: <code>PUSH</code>,\n                            <code>PULL_REQUEST_CREATED</code>, <code>PULL_REQUEST_UPDATED</code>, \n                            <code>PULL_REQUEST_CLOSED</code>, <code>PULL_REQUEST_REOPENED</code>, \n                            <code>PULL_REQUEST_MERGED</code>, <code>RELEASED</code>, <code>PRERELEASED</code>, \n                            and <code>WORKFLOW_JOB_QUEUED</code>. The <code>EVENT</code> patterns are\n                            specified as a comma-separated string. For example, <code>PUSH,\n                                PULL_REQUEST_CREATED, PULL_REQUEST_UPDATED</code> filters all push, pull\n                            request created, and pull request updated events. </p>\n                     <note>\n                        <p> Types <code>PULL_REQUEST_REOPENED</code> and <code>WORKFLOW_JOB_QUEUED</code> \n                                work with GitHub and GitHub Enterprise only. Types <code>RELEASED</code> and \n                                <code>PRERELEASED</code> work with GitHub only.</p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>ACTOR_ACCOUNT_ID</p>\n               <ul>\n                  <li>\n                     <p> A webhook event triggers a build when a GitHub, GitHub Enterprise, or\n                            Bitbucket account ID matches the regular expression <code>pattern</code>.\n                        </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>HEAD_REF</p>\n               <ul>\n                  <li>\n                     <p> A webhook event triggers a build when the head reference matches the\n                            regular expression <code>pattern</code>. For example,\n                            <code>refs/heads/branch-name</code> and <code>refs/tags/tag-name</code>. </p>\n                     <note>\n                        <p> Works with GitHub and GitHub Enterprise push, GitHub and GitHub\n                            Enterprise pull request, Bitbucket push, and Bitbucket pull request events.</p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>BASE_REF</p>\n               <ul>\n                  <li>\n                     <p> A webhook event triggers a build when the base reference matches the\n                            regular expression <code>pattern</code>. For example,\n                            <code>refs/heads/branch-name</code>. </p>\n                     <note>\n                        <p> Works with pull request events only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>FILE_PATH</p>\n               <ul>\n                  <li>\n                     <p> A webhook triggers a build when the path of a changed file matches the\n                            regular expression <code>pattern</code>. </p>\n                     <note>\n                        <p> Works with push and pull request events only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>COMMIT_MESSAGE</p>\n               <ul>\n                  <li>\n                     <p>A webhook triggers a build when the head commit message matches the\n                            regular expression <code>pattern</code>.</p>\n                     <note>\n                        <p> Works with push and pull request events only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>TAG_NAME</p>\n               <ul>\n                  <li>\n                     <p>A webhook triggers a build when the tag name of the release matches the \n                            regular expression <code>pattern</code>.</p>\n                     <note>\n                        <p> Works with <code>RELEASED</code> and <code>PRERELEASED</code> events only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>RELEASE_NAME</p>\n               <ul>\n                  <li>\n                     <p>A webhook triggers a build when the release name matches the \n                            regular expression <code>pattern</code>.</p>\n                     <note>\n                        <p> Works with <code>RELEASED</code> and <code>PRERELEASED</code> events only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>REPOSITORY_NAME</p>\n               <ul>\n                  <li>\n                     <p>A webhook triggers a build when the repository name matches the \n                                regular expression <code>pattern</code>.</p>\n                     <note>\n                        <p> Works with GitHub global or organization webhooks only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>ORGANIZATION_NAME</p>\n               <ul>\n                  <li>\n                     <p>A webhook triggers a build when the organization name matches the \n                                regular expression <code>pattern</code>.</p>\n                     <note>\n                        <p> Works with GitHub global webhooks only. </p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>WORKFLOW_NAME</p>\n               <ul>\n                  <li>\n                     <p>A webhook triggers a build when the workflow name matches the \n                            regular expression <code>pattern</code>.</p>\n                     <note>\n                        <p> Works with <code>WORKFLOW_JOB_QUEUED</code> events only. </p>\n                     </note>\n                     <note>\n                        <p>For CodeBuild-hosted Buildkite runner builds, WORKFLOW_NAME\n                                filters will filter by pipeline name.</p>\n                     </note>\n                  </li>\n               </ul>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
